mapper.update:

		 /* updateMasterWmGrStockWarehousingManagerPopIvdt */
			UPDATE ICOMIVDT SET WMS_GR_QTY = 0 , 
		            WMS_GR_DATE = '', 
					WMS_GR_USER_ID = '',
					GR_QTY = 0,	
					CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'), 
					CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS') 
			WHERE BUYER = #{ware_house_code}
  			  AND INV_NO = #{st_inv_no}


			/* updateMasterWmGrStockWarehousingManagerPopPodt */
						UPDATE ICOMPODT 
						     SET GR_QTY = GR_QTY - ${GR_QTY} , 
		            		      DI_QTY = DI_QTY - ${GR_QTY}    	
                        WHERE BUYER =#{ware_house_code} 
                           AND PO_NO = #{st_po_no} 
                           AND PO_SEQ = #{VPO_SEQ}


			/* deleteMasterWmGrStockWarehousingManagerPopGrDt */
						UPDATE ICOMGRDT SET STATUS = 'D' 
							WHERE BUYER = #{ware_house_code}    
  								AND INV_NO =  #{st_inv_no}
  								AND INV_SEQ = #{INV_SEQ}


			/* updateMasterWmGrStockWarehousingManagerPopWmsStckForSTCK */
			UPDATE WMSSTCK 
			    SET TOT_QTY = TOT_QTY - (${INV_QTY}), 
 					 AVAIL_QTY = AVAIL_QTY - (${INV_QTY}),   
 					 PRE_GR_QTY = PRE_GR_QTY + ${INV_QTY}, 
 					 STC_SELLER_PRICE = ROUND(DECODE(AVAIL_QTY- (${INV_QTY}),0,0,((AVAIL_QTY*STC_SELLER_PRICE)-(${INV_QTY}*${UNIT_PRICE}))/(AVAIL_QTY-(${INV_QTY}))),0) 		
		   WHERE WAREHOUSE_CODE =#{ware_house_code}    	
              AND STDCATLG_ID = (		 
                                           SELECT BUYER_ITEM_NO FROM ICOMPODT PO  
                                           WHERE PO.BUYER  = #{ware_house_code}    	
                                              AND PO.PO_NO  = #{st_po_no} 	
                                              AND PO.PO_SEQ =#{VPO_SEQ}	
                                         )							
               AND AGENT = 'KRKORE0001'	
               AND CONTRACT_NO = (		
                                              SELECT CONTRACT_NO 
                                               FROM ICOMPODT PO  
                                              WHERE PO.BUYER  = #{ware_house_code} 		
                                                 AND PO.PO_NO  = #{st_po_no} 		
                                                 AND PO.PO_SEQ =#{VPO_SEQ}	
                                              )							
              AND CONTRACT_SEQ = (		
                                               SELECT CONTRACT_SEQ 
                                                 FROM ICOMPODT PO  
                                                WHERE PO.BUYER  = #{ware_house_code} 	
                                                   AND PO.PO_NO  = #{st_po_no} 		
                                                   AND PO.PO_SEQ = #{VPO_SEQ}		
                                             )


				/* updateMasterWmGrStockWarehousingManagerPopEdidt */
  						UPDATE EDIVPODT 
  						     SET
                                  RECV_FLAG = 'B',  
                                  GR_QTY = 0,		
                                 RECV_USER_ID = '',
                                 VGR_DATE = ''     
                      WHERE  BUYER =  #{ware_house_code} 	  
                         AND VPO_NO = #{st_inv_no}
